/* Fill the gaps and nothing else. A row that already has a picture keeps
   the one it has, so the 91 entries of rows 0-119 and the 80 Picture Guess
   rounds are untouched whichever order these blocks load in, and no row
   number moves: QIMG is keyed by the TRIVIA row, which the page appends as
   column 7 and reads back as Q.qid.
   QIMG is deliberately NOT redeclared here. tools/bundle.py cuts this whole
   block into banks.js and rewrites a leading `var QIMG=` to a bare
   assignment, because index.html keeps `var QIMG={}` as a placeholder; a
   second declaration here would be rewritten too and would read oddly. The
   typeof guard works either way, in the page and in the chunk. */
if(typeof QIMG==='undefined'){QIMG={}}
for(var k in QIMG_NEW){if(!(k in QIMG))QIMG[k]=QIMG_NEW[k]}
